data.code:
# ~/.local/share/chezmoi/dot_gitconfig.tmpl
[user]
    name = {{ .name }}
    email = {{ if eq .class "work" }}{{ .work_email }}{{ else }}{{ .personal_email }}{{ end }}
    signingkey = {{ .gpg_signingkey }}

[commit]
{{- if eq .chezmoi.os "darwin" }}
    gpgsign = true
{{- else }}
    gpgsign = false
{{- end }}

[github]
    token = {{ (bitwarden "item" "github-personal").login.password }}
